import json, time, urllib.request, urllib.error
from datetime import datetime, timezone
B="http://localhost:8080"
tok=None
log=[]
def get_token():
    global tok
    r=urllib.request.Request(B+"/token",method="POST",data=b"")
    tok=json.load(urllib.request.urlopen(r))["token"]
def req(path):
    global tok
    for attempt in range(200):
        if tok is None: get_token()
        r=urllib.request.Request(B+path,headers={"Authorization":"Bearer "+tok})
        try:
            with urllib.request.urlopen(r) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as e:
            body=e.read().decode()[:200]
            log.append((path,e.code,dict(e.headers),body))
            if e.code==404: return None
            if e.code==401 or e.code==403: tok=None; continue
            if e.code==429:
                ra=e.headers.get("Retry-After")
                try: w=float(ra)
                except: 
                    try: w=float(json.loads(body).get("retry_after",1))
                    except: w=1
                time.sleep(w+0.05); continue
            time.sleep(0.5)
        except Exception as e:
            log.append((path,"exc",repr(e),""))
            time.sleep(0.5)
    raise RuntimeError(path)
orders=[];p=1
while p:
    d=req(f"/orders?page={p}")
    orders+=d["items"]
    p=int(d["next"].split("=")[1]) if d["next"] else None
    tp=d["total_pages"]
print("pages",tp,"listings",len(orders))
seen={};dups=0
for o in orders:
    if o["id"] in seen:
        dups+=1
        if seen[o["id"]]!=o: print("DIFFERING DUP",o,seen[o["id"]])
    else: seen[o["id"]]=o
start=datetime(2025,3,1,tzinfo=timezone.utc);end=datetime(2025,6,1,tzinfo=timezone.utc)
q=[]
for o in seen.values():
    if o["status"]!="shipped": continue
    t=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None: print("naive",o)
    if start<=t.astimezone(timezone.utc)<end: q.append(o)
cust={}
for o in q:
    c=o["customer_id"]
    if c not in cust: cust[c]=req(f"/customers/{c}")
reg={"north":0,"south":0,"east":0,"west":0};tot=0
for o in q:
    c=cust[o["customer_id"]]
    if c is None: print("missing cust",o); continue
    a=o["amount_cents"]*(100-c["discount_pct"])
    v=(a+50)//100
    reg[c["region"]]+=v;tot+=v
res={"total_cents":tot,"order_count":len(q),"duplicates_skipped":dups,"by_region":reg}
json.dump(res,open("/workspace/result.json","w"),indent=2)
print(res, sum(reg.values())==tot)
from collections import Counter
print(Counter((l[1]) for l in log))
print([l for l in log if l[1]!=429][:3]); print([l for l in log if l[1]==429][:2])
print(Counter(o["status"] for o in seen.values()), len(seen), set(type(o["amount_cents"]) for o in seen.values()))
